(* [comment removed for export] *)
Lemma req_res_munch : forall W LB mbs tbs verb ver h' LB' m m',
  req_res LB mbs tbs verb ver h' LB' m -> munch W m m' -> wmono rsegs m m' ->
  Forall (fun iv : Z * Z => hceil <= fst iv) W -> req_res LB mbs tbs verb ver h' LB' m'.
Proof.
  intros W LB mbs tbs verb ver h' LB' m m' (pt & At & H1 & H2 & H3 & H4 & BR & RC & ALT) MU WM FW.
  assert (DJ : forall A n, A + n <= hceil -> disjoint_from W A n).
  { intros A n HA. clear - FW HA. induction W as [|[lo hi] W IH]; [exact I|]. cbn.
    pose proof (Forall_inv FW) as K. cbn in K. split; [lia | apply IH; exact (Forall_inv_tail FW)]. }
  exists pt, At. repeat (split; [assumption|]). split.
  - eapply rw_cells_transport; [exact RC | exact MU | exact WM |]. apply DJ. destruct BR as (_ & _ & _ & B4 & _). cbn [cells_size csize Nat.add]. lia.
  - destruct ALT as [L | (V0 & pm & Am & G1 & G2 & BRm & RCm & G5)]; [left; exact L | right].
    split; [exact V0|]. exists pm, Am. repeat (split; [assumption|]). split; [| exact G5].
    eapply rw_cells_transport; [exact RCm | exact MU | exact WM |]. apply DJ. destruct BRm as (_ & _ & _ & B4 & _). cbn [cells_size csize Nat.add]. lia.
Qed.

Section SR.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.
  Hypothesis S2V : string_to_verb_stmt.
  Hypothesis ONREQ : onreq_stmt H.

(* [comment removed for export] *)
Definition isl_outcome (c : pcore) (p0 : Z) (bs : list byte) (h : hdrv) (LB : list block) (g : bool) (m' : mem)
    (c' : pcore) (in' : Z) (E' : ecv) (u' : Z) (h' : hdrv) (LB' : list block) (g' : bool) : Prop :=
  (exists e loc, c' = c /\ in' = p0 /\ E' = EC_http_loc e loc
      /\ In e [HE_NEED_MORE; HE_BAD_METHOD; HE_BAD_TARGET; HE_BAD_VERSION] /\ Z.even loc = true /\ 4 <= loc /\ loc + 1 < 2^64
      /\ u' = 0 /\ h' = h /\ LB' = LB /\ g' = true)
  \/ (exists (k j ver f1 : Z) (mbs tbs : list byte),
      c' = mkPC (pc_blim_has c) (pc_blim c) (pc_len c) (pc_len0 c) (pc_skip c) (pc_hlim c) 2 f1
      /\ (f1 = pc_f c \/ f1 = Z.lor (pc_f c) 16) /\ 0 <= f1 < 2^14
      /\ in' = p0 + k + j + 12 /\ 1 <= k /\ 1 <= j /\ p0 + k + j + 12 <= p0 + Z.of_nat (length bs)
      /\ E' = EC_clear /\ u' = 1 /\ (ver = 10 \/ ver = 11) /\ g' = g
      /\ bytes_at rsegs m' p0 mbs /\ bytes_at rsegs m' (p0 + k + 1) tbs /\ Z.of_nat (length mbs) = k /\ Z.of_nat (length tbs) = j
      /\ req_res LB mbs tbs (verb_of (zbytes mbs)) ver h' LB' m').

Definition isl_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (mo : Model) (LB : list block) (P IN E lo B : Z) (c : pcore) (pad7 pad2 : list byte) (p0 : Z) (bs : list byte)
    (h : hdrv) (g : bool) : config -> Prop :=
  fun cf => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState)
                   (c' : pcore) (in' : Z) (E' : ecv) (u' : Z) (h' : hdrv) (LB' : list block) (g' : bool),
    cfg_ms cf = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (ret_pc ra) fc None m' (seg_rom rsegs)
